    bg = grid[0][0]

    # Identify connected components of the background color starting from the border.
    # Any background pixel not reached will be considered enclosed.
    visited = [[False] * cols for _ in range(rows)]
    from collections import deque
    queue = deque()

    # Add border cells to queue if they are background color
    # Top and Bottom rows
    for c in range(cols):
        if grid[0][c] == bg:
